
package org.strathclyde.service;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class EventLog {

    // Stores all events generated by the spaceport.
    private final List<String> events = new ArrayList<>();

    // Records a new event.
    // Synchronized protects the shared event list
    // when multiple threads try to add events.
    public synchronized void recordEvent(
            String eventType,
            String transportId,
            String resourceId,
            String description) {

        // Get the current date and time.
        LocalDateTime timestamp = LocalDateTime.now();

        // Create the event entry.
        String event = timestamp
                + " | " + eventType
                + " | Transport: " + transportId
                + " | Resource: " + resourceId
                + " | " + description;

        // Add the event to the shared list.
        events.add(event);

        // Display the event in the console.
        System.out.println("EVENT LOG: " + event);
    }

    // Returns a safe copy of all recorded events.
    public synchronized List<String> getEvents() {
        return Collections.unmodifiableList(
                new ArrayList<>(events)
        );
    }
}
